<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<title>Snake</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #121212; color: #e0e0e0; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 100vh;
  }
  h1 { margin-bottom: 8px; color: #4caf50; letter-spacing: 2px; }
  #score-display { font-size: 20px; margin-bottom: 12px; color: #ffeb3b; }
  #snake-canvas-container { position: relative; }
  canvas#snake-board {
    display: block; border: 2px solid #4caf50; background: #1e1e1e; image-rendering: pixelated;
  }
  .controls { margin-top: 16px; display: flex; gap: 12px; }
  button {
    padding: 10px 24px; font-size: 15px; border: none; border-radius: 6px; cursor: pointer;
    font-weight: bold; transition: background 0.2s, transform 0.1s;
  }
  button:hover { transform: scale(1.05); }
  #start { background: #4caf50; color: #fff; }
  #pause  { background: #ff9800; color: #fff; }
  #reset  { background: #f44336; color: #fff; }
  button:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }
</style>
</head>
<body>

<h1>SNAKE</h1>
<div id="score-display">Score: <span id="score">0</span></div>
<div id="snake-canvas-container"><canvas id="snake-board" width="420" height="420"></canvas></div>
<div class="controls">
  <button id="start">Start</button>
  <button id="pause" disabled>Pause</button>
  <button id="reset">Reset</button>
</div>

<script>
(function () {
  // --- Config ---
  const CELL = 40;
  const W = 18, H = 18;
  const TICK_MS = 120;

  // --- Canvas ---
  const canvas = document.getElementById('snake-board');
  const ctx = canvas.getContext('2d');
  canvas.width = CELL * W;
  canvas.height = CELL * H;

  // --- State ---
  let snake, dir, nextDir, food, score, alive, running;

  function initState() {
    const cx = Math.floor(W / 2), cy = Math.floor(H / 2);
    snake = [
      [cx - 1, cy],
      [cx - 2, cy],
      [cx - 3, cy]
    ];
    dir = 'right'; nextDir = 'right';
    score = 0; alive = true; running = false;
  }

  function randomFreeCell() {
    const taken = new Set(snake.map(s => s[0] + ',' + s[1]));
    let x, y, attempts = W * H;
    while (attempts--) {
      x = Math.floor(Math.random() * W);
      y = Math.floor(Math.random() * H);
      if (!taken.has(x + ',' + y)) return [x, y];
    }
    // Fallback: scan first empty cell
    for (let i = 0; i < snake.length; i++) {
      const s = snake[i];
      for (let x = 0; x < W; x++) {
        for (let y = 0; y < H; y++) {
          if (x + ',' + y !== s[0] + ',' + s[1]) return [x, y];
        }
      }
    }
    return [0, 0];
  }

  function placeFood() { food = randomFreeCell(); }

  // --- Direction queue (ignore 180°) ---
  const DIRS = { up: { x: 0, y: -1 }, down: { x: 0, y: 1 }, left: { x: -1, y: 0 }, right: { x: 1, y: 0 } };

  function setDir(d) {
    if (!alive || !running) return;
    const current = DIRS[dir];
    const reverse = DIRS[d] && (DIRS[d].x === -current.x && DIRS[d].y === -current.y);
    if (!reverse) nextDir = d;
  }

  function tick() {
    if (!alive || !running) return;
    dir = nextDir;
    const head = snake[0];
    const nv = DIRS[dir];
    const nx = head[0] + nv.x, ny = head[1] + nv.y;

    // Wall collision
    if (nx < 0 || nx >= W || ny < 0 || ny >= H) { alive = false; return; }

    // Self collision
    for (let i = 0; i < snake.length; i++) {
      if (snake[i][0] === nx && snake[i][1] === ny) { alive = false; return; }
    }

    const newHead = [nx, ny];
    let ate = false;
    if (nx === food[0] && ny === food[1]) {
      score++; ate = true; placeFood();
    }
    snake.unshift(newHead);
    if (!ate) snake.pop();
  }

  // --- Rendering ---
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Grid lines (subtle)
    ctx.strokeStyle = '#2a2a2a';
    ctx.lineWidth = 0.5;
    for (let x = 1; x < W; x++) { ctx.beginPath(); ctx.moveTo(x * CELL, 0); ctx.lineTo(x * CELL, H * CELL); ctx.stroke(); }
    for (let y = 1; y < H; y++) { ctx.beginPath(); ctx.moveTo(0, y * CELL); ctx.lineTo(W * CELL, y * CELL); ctx.stroke(); }

    // Food
    const fx = food[0] * CELL + CELL / 2, fy = food[1] * CELL + CELL / 2;
    ctx.fillStyle = '#ff5252';
    ctx.shadowColor = '#ff5252';
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(fx, fy, CELL * 0.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Snake
    snake.forEach((seg, i) => {
      const x = seg[0] * CELL + CELL / 2, y = seg[1] * CELL + CELL / 2;
      const isHead = i === 0;
      ctx.fillStyle = isHead ? '#4caf50' : '#66bb6a';
      if (isHead) {
        ctx.shadowColor = '#4caf50';
        ctx.shadowBlur = 6;
      }
      ctx.beginPath();
      ctx.arc(x, y, CELL * 0.38, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;

      // Eyes on head
      if (isHead) {
        ctx.fillStyle = '#1b1b1b';
        const exOff = DIRS[dir].x * 3, eyOff = DIRS[dir].y * 3;
        ctx.beginPath();
        ctx.arc(x + exOff - 2, y + eyOff - 2, 2.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(x + exOff + 2, y + eyOff + 2, 2.5, 0, Math.PI * 2);
        ctx.fill();
      }
    });

    // Game over overlay
    if (!alive) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff5252';
      ctx.font = 'bold 36px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 10);
      ctx.font = '18px sans-serif';
      ctx.fillStyle = '#e0e0e0';
      ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2 + 25);
    }

    // Update score display
    document.getElementById('score').textContent = score;
  }

  function updateButtons() {
    const startBtn = document.getElementById('start');
    const pauseBtn = document.getElementById('pause');
    if (alive && running) {
      startBtn.textContent = 'Restart';
      startBtn.onclick = () => { initState(); placeFood(); draw(); };
      pauseBtn.disabled = false;
      pauseBtn.textContent = 'Pause';
      pauseBtn.onclick = () => { running = !running; pauseBtn.textContent = running ? 'Pause' : 'Resume'; };
    } else if (alive && !running) {
      startBtn.textContent = 'Start';
      startBtn.onclick = () => { initState(); placeFood(); draw(); };
      pauseBtn.disabled = true;
      pauseBtn.textContent = 'Pause';
    } else {
      startBtn.textContent = 'Restart';
      startBtn.onclick = () => { initState(); placeFood(); draw(); };
      pauseBtn.disabled = true;
      pauseBtn.textContent = 'Pause';
    }
  }

  // --- Expose API on window ---
  const game = {
    w: W, h: H,
    reset() { initState(); placeFood(); draw(); updateButtons(); },
    tick() { tick(); if (alive && running) { setTimeout(() => requestAnimationFrame(draw), TICK_MS); } else draw(); },
    setDir(d) { setDir(d); },
    setFood(x, y) { food = [x, y]; placeFood(); },
    snake() { return snake.map(s => [...s]); },
    food() { return [...food]; },
    alive() { return alive; },
    score() { return score; }
  };

  window.game = game;

  // --- Init ---
  initState(); placeFood(); draw(); updateButtons();

  // --- Keyboard input ---
  document.addEventListener('keydown', (e) => {
    const keyMap = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
    if (!keyMap[e.key]) return;
    e.preventDefault();
    setDir(keyMap[e.key]);
  });

  // --- Auto-advance loop ---
  function gameLoop() {
    if (alive && running) tick();
    setTimeout(gameLoop, TICK_MS);
  }
  setInterval(gameLoop, TICK_MS);

})();
</script>

</body>
</html>
